#include <stdio.h>

int main(void) {
    int b1, h1, b2, h2;
    scanf("%d %d %d %d", &b1, &h1, &b2, &h2);
    int a1 = b1 * h1;
    int a2 = b2 * h2;
    if (a1 > a2) {
        printf("primeiro maior\n");
    } else if (a2 > a1) {
        printf("segundo maior\n");
    } else {
        printf("iguais\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int band, desc;
    double kms, valor, corrida, min = 3.5;
    scanf("%d %lf %d", &band, &kms, &desc);
    if (band == 1) valor = 1.8;
    else valor = 2.3;
    corrida = valor * kms;
    if (desc == 1) corrida *= 0.7;
    if (corrida < min) corrida = min;
    printf("%.2f\n", corrida);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    if (a == b) {
        printf("iguais\n");
    } else {
        int maior = a > b ? a : b;
        if (maior % 2 == 0) printf("%d par\n", maior);
        else printf("%d impar\n", maior);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int num, c;
    scanf("%d", &num);
    c = num / 100;
    if (c % 2 == 0) {
        printf("par\n");
    } else {
        printf("impar\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int idade;
    scanf("%d", &idade);
    if (idade < 5) printf("sem categoria\n");
    else if (idade <= 7) printf("Infantil A\n");
    else if (idade <= 10) printf("Infantil B\n");
    else if (idade <= 13) printf("Juvenil A\n");
    else if (idade <= 17) printf("Juvenil B\n");
    else printf("Senior\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, soma = 0;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        printf("%d\n", i);
        soma += i;
    }
    printf("%d\n", soma);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        printf("%d%s", 2 * i, i == n ? "" : " ");
    }
    printf("\n");
    return 0;
}

